/**
 * Lightweight Markdown to HTML converter.
 * Handles: headings, code blocks, inline code, bold, italic, links,
 * lists (ul/ol), blockquotes, paragraphs, horizontal rules.
 */
const marked = { parse: (function() {
    function escapeHtml(s) {
        return s.replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;');
    }

    function parse(md) {
        if (!md) return '';
        let html = '';
        const lines = md.split('\n');
        let i = 0;

        while (i < lines.length) {
            const line = lines[i];

            // Fenced code block
            if (line.trimStart().startsWith('```')) {
                const lang = line.trim().slice(3).trim();
                let code = '';
                i++;
                while (i < lines.length && !lines[i].trimStart().startsWith('```')) {
                    code += escapeHtml(lines[i]) + '\n';
                    i++;
                }
                i++; // skip closing ```
                html += '<pre><code class="lang-' + (lang||'text') + '">' + code.replace(/\n$/,'') + '</code></pre>\n';
                continue;
            }

            // Horizontal rule
            if (/^(\*{3,}|-{3,}|_{3,})\s*$/.test(line.trim())) {
                html += '<hr>\n';
                i++;
                continue;
            }

            // Heading
            const hMatch = line.match(/^(#{1,6})\s+(.*)$/);
            if (hMatch) {
                const level = hMatch[1].length;
                html += '<h' + level + '>' + inline(hMatch[2]) + '</h' + level + '>\n';
                i++;
                continue;
            }

            // Blockquote
            if (line.trimStart().startsWith('> ')) {
                let bq = '';
                while (i < lines.length && lines[i].trimStart().startsWith('> ')) {
                    bq += lines[i].replace(/^>\s?/, '') + '\n';
                    i++;
                }
                html += '<blockquote>' + parse(bq) + '</blockquote>\n';
                continue;
            }

            // Unordered list
            if (/^\s*[-*+]\s+/.test(line)) {
                html += '<ul>\n';
                while (i < lines.length && /^\s*[-*+]\s+/.test(lines[i])) {
                    html += '<li>' + inline(lines[i].replace(/^\s*[-*+]\s+/, '')) + '</li>\n';
                    i++;
                }
                html += '</ul>\n';
                continue;
            }

            // Ordered list
            if (/^\s*\d+\.\s+/.test(line)) {
                html += '<ol>\n';
                while (i < lines.length && /^\s*\d+\.\s+/.test(lines[i])) {
                    html += '<li>' + inline(lines[i].replace(/^\s*\d+\.\s+/, '')) + '</li>\n';
                    i++;
                }
                html += '</ol>\n';
                continue;
            }

            // Blank line
            if (line.trim() === '') {
                i++;
                continue;
            }

            // Paragraph: collect consecutive non-blank, non-special lines
            let para = '';
            while (i < lines.length && lines[i].trim() !== '' &&
                   !lines[i].trimStart().startsWith('```') &&
                   !lines[i].trimStart().startsWith('# ') &&
                   !lines[i].trimStart().startsWith('## ') &&
                   !lines[i].trimStart().startsWith('### ') &&
                   !lines[i].trimStart().startsWith('> ') &&
                   !/^\s*[-*+]\s+/.test(lines[i]) &&
                   !/^\s*\d+\.\s+/.test(lines[i]) &&
                   !/^(\*{3,}|-{3,}|_{3,})\s*$/.test(lines[i].trim())) {
                para += lines[i] + ' ';
                i++;
            }
            if (para.trim()) {
                html += '<p>' + inline(para.trim()) + '</p>\n';
            }
        }
        return html;
    }

    function inline(text) {
        // Inline code
        text = text.replace(/`([^`]+)`/g, '<code>$1</code>');
        // Bold + italic
        text = text.replace(/\*\*\*(.+?)\*\*\*/g, '<strong><em>$1</em></strong>');
        // Bold
        text = text.replace(/\*\*(.+?)\*\*/g, '<strong>$1</strong>');
        // Italic
        text = text.replace(/\*(.+?)\*/g, '<em>$1</em>');
        // Links
        text = text.replace(/\[([^\]]+)\]\(([^)]+)\)/g, '<a href="$2">$1</a>');
        return text;
    }

    return parse;
})()};
